// Merge form fields with AI-extracted fields (form values win if filled in)

const body = $('Webhook HR').first().json.body;

let ai = {};
try {
  ai = JSON.parse($input.first().json.content.parts[0].text);
} catch (e) {}

const pick = (k) => (body[k] && String(body[k]).trim()) || ai[k] || '';

// Convert skills from comma-separated string → array
const toArray = (value) => {
  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string') {
    return value
      .split(',')
      .map(skill => skill.trim())
      .filter(skill => skill !== '');
  }

  return [];
};

return [{
  json: {
    action: body.action,
    job_code: String(body.job_code || '').trim().toUpperCase(), // NEW: unique Job ID
    job_id: body.job_id,
    job_title: pick('job_title'),
    department: pick('department'),
    location: pick('location'),
    job_description: pick('job_description'),
    required_skills: toArray(pick('required_skills')),
    preferred_skills: toArray(pick('preferred_skills')),

    min_experience_years: Number(pick('min_experience_years')) || 0
  }
}];

// Parse AI result safely and apply the score bands
const body = $('Webhook Candidate').first().json.body;
const job = $('Get Job').first().json;

// --- Was the CV readable? ---
const MIN_CHARS = 150;
const ext = String($('Extract CV').first().json.text || '').trim();
let cvOk = ext.length >= MIN_CHARS;
if (!cvOk) {
  try {
    const t = String($('Read Scanned CV').first().json.content.parts[0].text || '').trim();
    cvOk = t.length >= MIN_CHARS && !t.includes('NO_TEXT');
  } catch (e) { cvOk = false; }
}

let ai = null;
try {
  const raw = $input.first().json.content.parts[0].text;
  ai = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  ai = null;
}

const valid = ai && Number.isFinite(Number(ai.match_score));
const score = (valid && cvOk) ? Math.min(100, Math.max(0, Number(ai.match_score))) : 0;
const injected = !!(ai && ai.injection_detected === true);
// Unreadable CV or unusable AI answer: send to HR instead of rejecting
const status = (!valid || !cvOk || injected) ? 'HR Review'
  : score >= 75 ? 'Shortlisted'
  : score >= 60 ? 'HR Review'
  : 'Not Qualified';

return [{ json: {
  candidate_name: body.candidate_name || (ai && ai.candidate_name) || '',
  candidate_email: (body.candidate_email || '').trim().toLowerCase(),
  job_id: body.job_id,
  job_title: job.job_title,
  experience_yrs: (ai && cvOk) ? (Number(ai.total_experience_years) || 0) : 0,
  tech_stack: (ai && cvOk && Array.isArray(ai.tech_stack)) ? ai.tech_stack : [],
  match_score: score,
  status,
  analysis_summary: (injected ? 'WARNING: possible prompt injection detected in this CV. Review manually. ' : '') + (!cvOk   // CHANGED
    ? 'The CV text could not be read (blank, scanned or unsupported file). Please open the CV and review it manually.'
    : (valid ? ai.analysis_summary : 'AI scoring failed (invalid response). Please review this CV manually.')),
  cv_ok: cvOk
  // analysis_summary: !cvOk
  //   ? 'The CV text could not be read (blank, scanned or unsupported file). Please open the CV and review it manually.'
  //   : (valid ? ai.analysis_summary : 'AI scoring failed (invalid response). Please review this CV manually.'),
  // cv_ok: cvOk
}}];

const rows = $input.all().map(i => i.json).filter(r => r.status);

const shortlisted = rows.filter(r => r.status === 'Shortlisted').length;
const hrReview = rows.filter(r => r.status === 'HR Review').length;
const notQualified = rows.filter(r => r.status === 'Not Qualified').length;

