// ===== SETTINGS =====
const TZ = 'Asia/Karachi';
const START_HOUR = 9, END_HOUR = 17;   // interview window: 9:00 AM to 5:00 PM
const DURATION_MIN = 10;               // interview length in minutes
const DAILY_CAP = 50;                  // maximum interviews per day
const MAX_DAYS = 30;                   // how many days ahead to look
// =====================

const cands = $('Filter Unscheduled').all().map(i => i.json);
const dur = DURATION_MIN * 60000;

const events = $input.all().map(i => i.json)
  .filter(e => e.start && e.start.dateTime && e.end && e.end.dateTime && e.status !== 'cancelled');
const busy = events.map(e => [new Date(e.start.dateTime).getTime(), new Date(e.end.dateTime).getTime()]);

const dayKey = ms => new Date(ms).toLocaleDateString('en-CA', { timeZone: TZ });
const used = {};
for (const e of events) {
  if ((e.summary || '').startsWith('Interview - ')) {
    const k = dayKey(new Date(e.start.dateTime).getTime());
    used[k] = (used[k] || 0) + 1;
  }
}

const first = $now.setZone(TZ).plus({ days: 1 }).startOf('day');   // scheduling starts next working day
const out = [];
for (const c of cands) {
  let slot = null;
  for (let d = 0; d < MAX_DAYS && !slot; d++) {
    const day = first.plus({ days: d });
    if (day.weekday > 5) continue;                                  // skip Saturday and Sunday
    const key = day.toISODate();
    const close = day.set({ hour: END_HOUR }).toMillis();
    let t = day.set({ hour: START_HOUR }).toMillis();
    while (t + dur <= close && (used[key] || 0) < DAILY_CAP) {
      const end = t + dur;
      const clash = busy.find(([bs, be]) => t < be && end > bs);
      if (clash) { t = Math.max(t + 60000, clash[1]); continue; }   // jump past the conflict
      slot = { start: t, end, key };
      break;
    }
  }
  if (!slot) throw new Error('No free interview slot in the next ' + MAX_DAYS + ' days for ' + c.candidate_name);
  busy.push([slot.start, slot.end]);
  used[slot.key] = (used[slot.key] || 0) + 1;

  const fmtTime = ms => new Date(ms).toLocaleTimeString('en-US', { timeZone: TZ, hour: 'numeric', minute: '2-digit' });
  out.push({ json: {
    ...c,
    interview_date: slot.key,
    slot_start: new Date(slot.start).toISOString(),
    slot_end: new Date(slot.end).toISOString(),
    date_label: new Date(slot.start).toLocaleDateString('en-GB', { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }),
    time_label: fmtTime(slot.start) + ' - ' + fmtTime(slot.end)
  } });
}
return out;

// ===== SETTINGS (keep the same as "Assign Slots1") =====
const TZ = 'Asia/Karachi';
const START_HOUR = 9, END_HOUR = 17;   // interview window: 9:00 AM to 5:00 PM
const DURATION_MIN = 10;               // interview length in minutes
const MAX_DAYS = 30;                   // how many days ahead to look
// =======================================================

const body = $('Webhook Interview Reschedule').first().json.body;
const cand = $('Resched Get Candidate').first().json;
const own = String(body.interview_event_id || '');


//Safety check (same idea as the 7 PM scheduler): only an interview that is still Scheduled,
// and still the same one HR is looking at, can be moved. This stops double bookings.
/**if (cand.interview_status !== 'Scheduled' || !cand.interview_event_id || String(cand.interview_event_id) !== own) {
  return [{ json: { ok: false, error: 'changed', message: 'This interview was already changed. Close this window and refresh the list.' } }];
}
  /** // Cancelled interviews can be reinstated. Scheduled ones can only be moved if HR is looking at the current event.
   const reinstate = cand.interview_status === 'Cancelled';
   if (!reinstate && (cand.interview_status !== 'Scheduled' || !cand.interview_event_id || String(cand.interview_event_id) !== own)) {
     return [{ json: { ok: false, error: 'changed', message: 'This interview was already changed. Close this window and refresh the list.' } }];
   }**/

const reinstate = cand.interview_status === 'Cancelled';
// A cancelled interview can be booked again. A scheduled one can only be moved
// if HR is looking at the current event (stops double bookings).
if (!reinstate && (cand.interview_status !== 'Scheduled' || !cand.interview_event_id || String(cand.interview_event_id) !== own)) {
  return [{ json: { ok: false, error: 'changed', message: 'This interview was already changed. Close this window and refresh the list.' } }];
}

const manual = body.mode === 'manual';
const dur = DURATION_MIN * 60000;

// Busy times. For a manual pick, the candidate's own current event does not count as busy (it is being moved).
const busy = $input.all().map(i => i.json)
  .filter(e => e.start && e.start.dateTime && e.end && e.end.dateTime && e.status !== 'cancelled')
  .filter(e => !(manual && e.id === own))
  .map(e => [new Date(e.start.dateTime).getTime(), new Date(e.end.dateTime).getTime()]);

let start = null;
if (manual) {
  const dt = DateTime.fromISO(body.new_date + 'T' + body.new_start_time, { zone: TZ });
  if (!dt.isValid) throw new Error('Invalid date or time');
  start = dt.toMillis();
  if (busy.some(([bs, be]) => start < be && start + dur > bs)) {
    return [{ json: { ok: false, error: 'slot_unavailable', message: 'That time is already booked.' } }];
  }
} else {
  const first = $now.setZone(TZ).plus({ days: 1 }).startOf('day');   // same as the 7 PM scheduler: from the next working day
  for (let d = 0; d < MAX_DAYS && start === null; d++) {
    const day = first.plus({ days: d });
    if (day.weekday > 5) continue;                                   // skip Saturday and Sunday
    const close = day.set({ hour: END_HOUR }).toMillis();
    let t = day.set({ hour: START_HOUR }).toMillis();
    while (t + dur <= close) {
      const clash = busy.find(([bs, be]) => t < be && t + dur > bs);
      if (clash) { t = Math.max(t + 60000, clash[1]); continue; }
      start = t; break;
    }
  }
  if (start === null) throw new Error('No free interview slot in the next ' + MAX_DAYS + ' days');
}

const end = start + dur;
const fmtTime = ms => new Date(ms).toLocaleTimeString('en-US', { timeZone: TZ, hour: 'numeric', minute: '2-digit' });
return [{ json: {
  ok: true,
  candidate_id: cand.id,
  reinstate,
  candidate_name: cand.candidate_name,
  candidate_email: cand.candidate_email,
  job_title: cand.job_title,
  event_id: own,
  interview_date: DateTime.fromMillis(start, { zone: TZ }).toISODate(),
  slot_start: new Date(start).toISOString(),
  slot_end: new Date(end).toISOString(),
  date_label: new Date(start).toLocaleDateString('en-GB', { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }),
  time_label: fmtTime(start) + ' - ' + fmtTime(end)
} }];

let k = null;
try {
  const raw = $input.first().json.content.parts[0].text;
  k = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) { k = null; }
if (!k) return [{ json: { interview_kit: '' } }];

const iq = k.interview_questions || {};
const num = (arr) => (arr || []).map((x, i) => `${i + 1}. ${x.question}${x.reason ? '\nWhy: ' + x.reason : ''}`).join('\n') || '- None';
const gaps = (k.cv_gaps || []).map(g => `- ${g.requirement} (${g.status}). Ask: ${g.verification_question}`).join('\n') || '- None found';
const flags = (k.red_flags || []).map(f => `- [${f.type}] ${f.issue}. Evidence: ${f.evidence}. Ask: ${f.verification_question}`).join('\n') || 'No significant red flags identified from the provided CV.';
const focus = (k.focus_areas || []).map(f => '- ' + f).join('\n');

const kit = 'TECHNICAL QUESTIONS\n' + num(iq.technical_role_specific)
  + '\n\nCV VERIFICATION QUESTIONS\n' + num(iq.cv_verification)
  + '\n\nCV GAPS\n' + gaps
  + '\n\nPOINTS TO CLARIFY (RED FLAGS)\n' + flags
  + '\n\nFOCUS AREAS\n' + focus;
return [{ json: { interview_kit: kit } }];

